volatile uint32_t glDMARxCount = 0;               /* Counter to track the number of buffers received from USB. */
volatile uint32_t glDMATxCount = 0;               /* Counter to track the number of buffers sent to USB. */
volatile uint32_t glPibErrors = 0, glDmaErrors = 0, glLastError = 0;
uint32_t glStatus[8] __attribute__((aligned(32)));
uint32_t glGpifStatus[8] __attribute__((aligned(32)));
volatile uint32_t glGpifPhase = 0, glLastPibErrorPhase = 0;
volatile uint32_t glErrorsBeforeStart = 0, glErrorsAfterStart = 0;

if (type == CYU3P_PIB_INTR_ERROR) {
        ++glPibErrors;
        glLastError = 0x80000000u | argument;
        glLastPibErrorPhase = glGpifPhase;

/* Arm GPIF only after both DMA channels are ready. Pin configuration is retained across USB resets. */
apiRetStatus = CyU3PGpifSocketConfigure(0, CY_U3P_PIB_SOCKET_0, VAPOR_WATERMARK, CyFalse, 1);
if (apiRetStatus != CY_U3P_SUCCESS) CyFxAppErrorHandler(apiRetStatus);
apiRetStatus = CyU3PGpifSocketConfigure(3, CY_U3P_PIB_SOCKET_3, VAPOR_WATERMARK, CyFalse, 1);
if (apiRetStatus != CY_U3P_SUCCESS) CyFxAppErrorHandler(apiRetStatus);
glErrorsBeforeStart = glPibErrors;
glGpifPhase = 3;
apiRetStatus = CyU3PGpifSMStart(SYNC_SLAVE_FIFO_2BIT_RESET, SYNC_SLAVE_FIFO_2BIT_ALPHA_RESET);
if (apiRetStatus != CY_U3P_SUCCESS) CyFxAppErrorHandler(apiRetStatus);
glErrorsAfterStart = glPibErrors;
glGpifPhase = 4;

/* Read-only diagnostic request: C0 B0 0000 0000, up to 32 bytes. */
    if (bReqType == 0xC0 && bRequest == 0xB0 && wValue == 0 && wIndex == 0) {
        uint16_t length = (uint16_t)(setupdat1 >> 16);
        glStatus[0] = VAPOR_MAPPING_VERSION;
        glStatus[1] = glIsApplnActive;
        glStatus[2] = glPibErrors;
        glStatus[3] = glDmaErrors;
        glStatus[4] = glLastError;
        glStatus[5] = glDMARxCount;
        glStatus[6] = glDMATxCount;
        glStatus[7] = ((uint32_t)VAPOR_DMA_BYTES << 16) | VAPOR_WATERMARK;
        if (length > sizeof(glStatus)) length = sizeof(glStatus);
        CyU3PUsbSendEP0Data(length, (uint8_t *)glStatus);
        return CyTrue;
    }

    /* GP01 diagnostic build: live registers and callback phase snapshots.
     * Reading these registers neither clears errors nor restarts GPIF. */
    if (bReqType == 0xC0 && bRequest == 0xB1 && wValue == 0 && wIndex == 0) {
        uint16_t length = (uint16_t)(setupdat1 >> 16);
        glGpifStatus[0] = 0x31305047u; /* ASCII GP01, little endian. */
        glGpifStatus[1] = VAPOR_GPIF_BUS_CONFIG;
        glGpifStatus[2] = VAPOR_GPIF_WAVE_STATUS;
        glGpifStatus[3] = VAPOR_GPIF_STATUS;
        glGpifStatus[4] = glGpifPhase;
        glGpifStatus[5] = glLastPibErrorPhase;
        glGpifStatus[6] = glErrorsBeforeStart;
        glGpifStatus[7] = glErrorsAfterStart;
        if (length > sizeof(glGpifStatus)) length = sizeof(glGpifStatus);
        CyU3PUsbSendEP0Data(length, (uint8_t *)glGpifStatus);
        return CyTrue;
    }

    if (bType == CY_U3P_USB_STANDARD_RQT)

CyU3PPibRegisterCallback(CyFxPibCallback, CYU3P_PIB_INTR_ERROR);
    /* Define flag outputs before USB enumeration. Start the waveform only after SETCONF. */
    glGpifPhase = 1;
    apiRetStatus = CyU3PGpifLoad(&Sync_Slave_Fifo_2Bit_CyFxGpifConfig);
    if (apiRetStatus != CY_U3P_SUCCESS) CyFxAppErrorHandler(apiRetStatus);
    glGpifPhase = 2;
